// Preconditions: library must be initialized; bound > 0 per API
int inited = FUZZ_GET_ATTR_INT_GLOBAL("bcl_inited");
int started = FUZZ_GET_ATTR_INT_GLOBAL("bcl_started");
if (!inited && !started) { FUZZ_BAIL(); }
// Generate a positive bound within the representable range of BclRandInt
BclRandInt bound = (BclRandInt)*FUZZ_PARAM(unsigned long long);
if (bound == (BclRandInt)0) { bound = (BclRandInt)1; }
BclRandInt r = bcl_rand_bounded(bound);
// Property: result should be in [0, bound)
FUZZ_ASSERT(r < bound, "bcl_rand_bounded result not in [0,bound)");
(void)r;
// Validation: bound validity enforced, result range-checked

// Create a new BclContext wrapper object for the pool
// Preconditions: library must be initialized by start/end or init/free
int inited = FUZZ_GET_ATTR_INT_GLOBAL("bcl_inited");
int started = FUZZ_GET_ATTR_INT_GLOBAL("bcl_started");
if (!inited && !started) { FUZZ_BAIL(); }

// Construct a new context via API and wrap it into a heap object for persistence
BclContext v = bcl_ctxt_create();
if (v == (BclContext)NULL) { FUZZ_BAIL(); }
BclContext *ctxt = new BclContext; // wrapper owned by fuzzer pool
*ctxt = v;

// Track lifetime and an epoch counter for numbers owned by this context
FUZZ_SET_ATTR_INT(ctxt, "freed", 0);
FUZZ_SET_ATTR_INT(ctxt, "nums_epoch", 0);

// Do not push the context automatically; pushing/popping is handled by dedicated stubs
// Validation: ensure attributes reflect a live, newly-created context
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(ctxt, "freed") == 0, "new context not marked live");
